namespace sv_651945471e1b418b94a4c8449f3927f3.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);

public record NotificationPrefs(
    bool EmailNotifications,
    bool PushNotifications,
    bool WeeklyDigest,
    List<string> MutedChannels);

public record SecuritySettings(
    bool TwoFactorEnabled,
    DateTime? LastPasswordChange,
    List<ActiveSession> Sessions);

public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);

public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@* Vertical tab navigation for the settings dashboard *@

<nav class="settings-sidebar">
    <h5 class="sidebar-title">Settings</h5>
    <ul class="nav flex-column">
        @foreach (var section in Sections)
        {
            <li class="nav-item">
                <button class="nav-link @(section == ActiveSection ? "active" : "")"
                        @onclick="() => OnSectionChanged.InvokeAsync(section)">
                    <span class="section-icon">@GetIcon(section)</span>
                    @section
                </button>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter, EditorRequired]
    public string ActiveSection { get; set; } = "";

    [Parameter, EditorRequired]
    public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = ["Profile", "Notifications", "Security", "Appearance"];

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

.settings-sidebar {
    background: #f8f9fa;
    border-right: 1px solid #dee2e6;
    padding: 1.5rem 0;
    min-height: 100%;
}

.sidebar-title {
    padding: 0 1.25rem 1rem;
    margin-bottom: 0.5rem;
    font-weight: 600;
    color: #495057;
    border-bottom: 1px solid #dee2e6;
}

.nav-link {
    display: flex;
    align-items: center;
    gap: 0.625rem;
    padding: 0.75rem 1.25rem;
    color: #495057;
    border: none;
    background: none;
    width: 100%;
    text-align: left;
    font-size: 0.95rem;
    cursor: pointer;
    border-left: 3px solid transparent;
    transition: all 0.15s ease;
}

.nav-link:hover {
    background: #e9ecef;
    color: #212529;
}

.nav-link.active {
    background: #e7f1ff;
    color: #0d6efd;
    border-left-color: #0d6efd;
    font-weight: 600;
}

.section-icon {
    font-size: 1.1rem;
}

@* Profile editing form with avatar preview, save and discard *@

<div class="settings-section">
    <h4>Profile</h4>
    <p class="text-muted">Manage your personal information.</p>
    <hr />

    <div class="row">
        <div class="col-md-8">
            <div class="mb-3">
                <label class="form-label" for="displayName">Display Name</label>
                <input id="displayName" type="text" class="form-control"
                       @bind="EditDisplayName" @bind:event="oninput" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="email">Email</label>
                <input id="email" type="email" class="form-control"
                       @bind="EditEmail" @bind:event="oninput" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="bio">Bio</label>
                <textarea id="bio" class="form-control" rows="4"
                          @bind="EditBio" @bind:event="oninput"></textarea>
            </div>
        </div>

        <div class="col-md-4">
            <div class="avatar-preview">
                <label class="form-label">Avatar Preview</label>
                <div class="avatar-frame">
                    @if (!string.IsNullOrWhiteSpace(Profile?.AvatarUrl))
                    {
                        <img src="@Profile.AvatarUrl" alt="Avatar" class="avatar-img" />
                    }
                    else
                    {
                        <div class="avatar-placeholder">👤</div>
                    }
                </div>
                <small class="text-muted text-break mt-2 d-block">@Profile?.AvatarUrl</small>
            </div>
        </div>
    </div>

    <div class="d-flex gap-2 mt-3">
        <button class="btn btn-primary" @onclick="Save" disabled="@Saving">
            @if (Saving)
            {
                <span class="spinner-border spinner-border-sm me-1"></span>
            }
            Save Changes
        </button>
        <button class="btn btn-outline-secondary" @onclick="Discard" disabled="@Saving">
            Discard Changes
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public UserProfile? Profile { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<UserProfile> OnSave { get; set; }

    [Parameter, EditorRequired]
    public EventCallback OnDiscard { get; set; }

    private string EditDisplayName { get; set; } = "";
    private string EditEmail { get; set; } = "";
    private string EditBio { get; set; } = "";
    private bool Saving { get; set; }

    protected override void OnParametersSet()
    {
        if (Profile is not null)
        {
            EditDisplayName = Profile.DisplayName;
            EditEmail = Profile.Email;
            EditBio = Profile.Bio;
        }
    }

    private async Task Save()
    {
        if (Profile is null) return;
        Saving = true;
        var updated = Profile with
        {
            DisplayName = EditDisplayName,
            Email = EditEmail,
            Bio = EditBio
        };
        await OnSave.InvokeAsync(updated);
        Saving = false;
    }

    private async Task Discard()
    {
        await OnDiscard.InvokeAsync();
    }
}

.avatar-preview {
    text-align: center;
}

.avatar-frame {
    width: 128px;
    height: 128px;
    border-radius: 50%;
    overflow: hidden;
    margin: 0 auto;
    border: 3px solid #dee2e6;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #f8f9fa;
}

.avatar-img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.avatar-placeholder {
    font-size: 3rem;
    color: #adb5bd;
}

@* Notification toggles and muted channel list *@

<div class="settings-section">
    <h4>Notifications</h4>
    <p class="text-muted">Choose how you want to be notified.</p>
    <hr />

    <div class="mb-4">
        <div class="form-check form-switch mb-3">
            <input class="form-check-input" type="checkbox" id="emailNotif"
                   checked="@EditEmailNotifications"
                   @onchange="e => EditEmailNotifications = (bool)(e.Value ?? false)" />
            <label class="form-check-label" for="emailNotif">
                Email Notifications
            </label>
        </div>

        <div class="form-check form-switch mb-3">
            <input class="form-check-input" type="checkbox" id="pushNotif"
                   checked="@EditPushNotifications"
                   @onchange="e => EditPushNotifications = (bool)(e.Value ?? false)" />
            <label class="form-check-label" for="pushNotif">
                Push Notifications
            </label>
        </div>

        <div class="form-check form-switch mb-3">
            <input class="form-check-input" type="checkbox" id="weeklyDigest"
                   checked="@EditWeeklyDigest"
                   @onchange="e => EditWeeklyDigest = (bool)(e.Value ?? false)" />
            <label class="form-check-label" for="weeklyDigest">
                Weekly Digest
            </label>
        </div>
    </div>

    @if (AvailableChannels.Count > 0)
    {
        <h6>Muted Channels</h6>
        <div class="channel-list mb-4">
            @foreach (var channel in AvailableChannels)
            {
                var isMuted = MutedChannels.Contains(channel);
                <div class="form-check mb-2">
                    <input class="form-check-input" type="checkbox" id="@($"ch-{channel}")"
                           checked="@isMuted"
                           @onchange="e => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                    <label class="form-check-label" for="@($"ch-{channel}")">
                        @channel
                    </label>
                </div>
            }
        </div>
    }

    <button class="btn btn-primary" @onclick="Save" disabled="@Saving">
        @if (Saving)
        {
            <span class="spinner-border spinner-border-sm me-1"></span>
        }
        Save Preferences
    </button>
</div>

@code {
    [Parameter, EditorRequired]
    public NotificationPrefs? Prefs { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<NotificationPrefs> OnSave { get; set; }

    /// <summary>All channels available in the application.</summary>
    [Parameter]
    public List<string> AvailableChannels { get; set; } = [];

    private bool EditEmailNotifications { get; set; }
    private bool EditPushNotifications { get; set; }
    private bool EditWeeklyDigest { get; set; }
    private HashSet<string> MutedChannels { get; set; } = [];
    private bool Saving { get; set; }

    protected override void OnParametersSet()
    {
        if (Prefs is not null)
        {
            EditEmailNotifications = Prefs.EmailNotifications;
            EditPushNotifications = Prefs.PushNotifications;
            EditWeeklyDigest = Prefs.WeeklyDigest;
            MutedChannels = [.. Prefs.MutedChannels];
        }
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted)
            MutedChannels.Add(channel);
        else
            MutedChannels.Remove(channel);
    }

    private async Task Save()
    {
        Saving = true;
        var updated = new NotificationPrefs(
            EditEmailNotifications,
            EditPushNotifications,
            EditWeeklyDigest,
            MutedChannels.ToList());
        await OnSave.InvokeAsync(updated);
        Saving = false;
    }
}

@* Expandable change-password form *@

<div class="card mb-4">
    <div class="card-header d-flex justify-content-between align-items-center"
         style="cursor:pointer" @onclick="() => IsExpanded = !IsExpanded">
        <span>🔑 Change Password</span>
        <span>@(IsExpanded ? "▲" : "▼")</span>
    </div>

    @if (IsExpanded)
    {
        <div class="card-body">
            @if (!string.IsNullOrEmpty(ErrorMessage))
            {
                <div class="alert alert-danger">@ErrorMessage</div>
            }

            <div class="mb-3">
                <label class="form-label" for="currentPwd">Current Password</label>
                <input id="currentPwd" type="password" class="form-control"
                       @bind="CurrentPassword" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="newPwd">New Password</label>
                <input id="newPwd" type="password" class="form-control"
                       @bind="NewPassword" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="confirmPwd">Confirm Password</label>
                <input id="confirmPwd" type="password" class="form-control"
                       @bind="ConfirmPassword" />
            </div>

            <button class="btn btn-warning" @onclick="Submit" disabled="@Submitting">
                @if (Submitting)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Update Password
            </button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public EventCallback<(string Current, string New)> OnChangePassword { get; set; }

    private bool IsExpanded { get; set; }
    private string CurrentPassword { get; set; } = "";
    private string NewPassword { get; set; } = "";
    private string ConfirmPassword { get; set; } = "";
    private string? ErrorMessage { get; set; }
    private bool Submitting { get; set; }

    private async Task Submit()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(CurrentPassword) ||
            string.IsNullOrWhiteSpace(NewPassword))
        {
            ErrorMessage = "All password fields are required.";
            return;
        }

        if (NewPassword != ConfirmPassword)
        {
            ErrorMessage = "New password and confirmation do not match.";
            return;
        }

        Submitting = true;
        await OnChangePassword.InvokeAsync((CurrentPassword, NewPassword));
        Submitting = false;

        // Clear fields on success
        CurrentPassword = "";
        NewPassword = "";
        ConfirmPassword = "";
    }
}

.modal-backdrop {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.5);
    z-index: 1040;
