@* Security settings: password, 2FA, active sessions *@

<div class="settings-section">
    <h4>Security</h4>
    <p class="text-muted">Manage your account security.</p>
    <hr />

    <ChangePasswordPanel OnChangePassword="OnChangePassword" />

    <div class="card mb-4">
        <div class="card-body d-flex justify-content-between align-items-center">
            <div>
                <h6 class="mb-1">Two-Factor Authentication</h6>
                <span class="badge @(TwoFactorEnabled ? "bg-success" : "bg-secondary")">
                    @(TwoFactorEnabled ? "Enabled" : "Disabled")
                </span>
            </div>
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" id="twoFactor"
                       checked="@TwoFactorEnabled"
                       @onchange="e => OnToggle2FA.InvokeAsync((bool)(e.Value ?? false))" />
            </div>
        </div>
    </div>

    @if (Security?.LastPasswordChange is not null)
    {
        <p class="text-muted small">
            Last password change: @Security.LastPasswordChange.Value.ToString("MMMM d, yyyy")
        </p>
    }

    <h6>Active Sessions</h6>
    @if (Security?.Sessions is { Count: > 0 })
    {
        <div class="table-responsive">
            <table class="table table-hover align-middle">
                <thead class="table-light">
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in Security.Sessions)
                    {
                        var isCurrent = session.Id == CurrentSessionId;
                        <tr>
                            <td>
                                @session.Device
                                @if (isCurrent)
                                {
                                    <span class="badge bg-primary ms-1">Current</span>
                                }
                            </td>
                            <td>@session.Location</td>
                            <td>@session.LastActive.ToString("g")</td>
                            <td>
                                @if (!isCurrent)
                                {
                                    <button class="btn btn-sm btn-outline-danger"
                                            @onclick="() => SessionToRevoke = session">
                                        Revoke
                                    </button>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    }
    else
    {
        <p class="text-muted">No active sessions found.</p>
    }
</div>

<RevokeSessionDialog Session="@SessionToRevoke"
                     OnConfirm="ConfirmRevoke"
                     OnCancel="() => SessionToRevoke = null" />

@code {
    [Parameter, EditorRequired]
    public SecuritySettings? Security { get; set; }

    [Parameter]
    public bool TwoFactorEnabled { get; set; }

    /// <summary>ID of the current browser session (excluded from revocation).</summary>
    [Parameter]
    public string CurrentSessionId { get; set; } = "";

    [Parameter, EditorRequired]
    public EventCallback<(string Current, string New)> OnChangePassword { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<bool> OnToggle2FA { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<string> OnRevokeSession { get; set; }

    private ActiveSession? SessionToRevoke { get; set; }

    private async Task ConfirmRevoke()
    {
        if (SessionToRevoke is not null)
        {
            await OnRevokeSession.InvokeAsync(SessionToRevoke.Id);
            SessionToRevoke = null;
        }
    }
}

@* Appearance settings with live preview *@

