<div class="settings-section">
    <h4>Appearance</h4>
    <p class="text-muted">Customize how the application looks.</p>
    <hr />

    <div class="row">
        <div class="col-md-7">
            <div class="mb-4">
                <h6>Theme</h6>
                @foreach (var theme in new[] { "Light", "Dark", "System" })
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="theme"
                               id="@($"theme-{theme}")"
                               checked="@(EditTheme == theme)"
                               @onchange="() => EditTheme = theme" />
                        <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                    </div>
                }
            </div>

            <div class="mb-4">
                <h6>Font Size</h6>
                @foreach (var size in new[] { "Small", "Medium", "Large" })
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="fontSize"
                               id="@($"fs-{size}")"
                               checked="@(EditFontSize == size)"
                               @onchange="() => EditFontSize = size" />
                        <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                    </div>
                }
            </div>

            <div class="mb-4">
                <label class="form-label" for="language"><h6 class="d-inline">Language</h6></label>
                <select id="language" class="form-select w-auto"
                        @bind="EditLanguage">
                    <option value="en">English</option>
                    <option value="es">Español</option>
                    <option value="fr">Français</option>
                    <option value="de">Deutsch</option>
                    <option value="ja">日本語</option>
                    <option value="zh">中文</option>
                </select>
            </div>

            <div class="mb-4">
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="compactMode"
                           checked="@EditCompactMode"
                           @onchange="e => EditCompactMode = (bool)(e.Value ?? false)" />
                    <label class="form-check-label" for="compactMode">Compact Mode</label>
                </div>
            </div>

            <button class="btn btn-primary" @onclick="Save" disabled="@Saving">
                @if (Saving)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Save
            </button>
        </div>

        <div class="col-md-5">
            <h6>Preview</h6>
            <div class="preview-card @PreviewThemeClass" style="font-size: @PreviewFontSize;">
                <div class="preview-header">
                    <strong>Dashboard</strong>
                </div>
                <div class="preview-body" style="padding: @(EditCompactMode ? "0.5rem" : "1rem");">
                    <p class="preview-text">
                        Welcome back! You have <strong>3</strong> new notifications.
                    </p>
                    <div class="preview-items">
                        <div class="preview-item" style="padding: @(EditCompactMode ? "0.25rem 0.5rem" : "0.5rem 0.75rem");">Item 1</div>
                        <div class="preview-item" style="padding: @(EditCompactMode ? "0.25rem 0.5rem" : "0.5rem 0.75rem");">Item 2</div>
                        <div class="preview-item" style="padding: @(EditCompactMode ? "0.25rem 0.5rem" : "0.5rem 0.75rem");">Item 3</div>
                    </div>
                    <button class="preview-btn">Action</button>
                </div>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public AppearanceSettings? Appearance { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string EditTheme { get; set; } = "Light";
    private string EditFontSize { get; set; } = "Medium";
    private string EditLanguage { get; set; } = "en";
    private bool EditCompactMode { get; set; }
    private bool Saving { get; set; }

    private string PreviewThemeClass => EditTheme switch
    {
        "Dark" => "preview-dark",
        _ => "preview-light"
    };

    private string PreviewFontSize => EditFontSize switch
    {
        "Small" => "0.8rem",
        "Large" => "1.15rem",
        _ => "0.95rem"
    };

    protected override void OnParametersSet()
    {
        if (Appearance is not null)
        {
            EditTheme = Appearance.Theme;
            EditFontSize = Appearance.FontSize;
            EditLanguage = Appearance.Language;
            EditCompactMode = Appearance.CompactMode;
        }
    }

    private async Task Save()
    {
        Saving = true;
        var updated = new AppearanceSettings(EditTheme, EditFontSize, EditLanguage, EditCompactMode);
        await OnSave.InvokeAsync(updated);
        Saving = false;
    }
}
"}

