@using sv_651945471e1b418b94a4c8449f3927f3.Components.Pages.Settings

@* Security settings: password, 2FA, active sessions *@

<div class="settings-section">
    <h4>Security</h4>
    <p class="text-muted">Manage your account security.</p>
    <hr />

    <ChangePasswordPanel OnChangePassword="OnChangePassword" />

    <div class="card mb-4">
        <div class="card-body d-flex justify-content-between align-items-center">
            <div>
                <h6 class="mb-1">Two-Factor Authentication</h6>
                <span class="badge @(TwoFactorEnabled ? "bg-success" : "bg-secondary")">
                    @(TwoFactorEnabled ? "Enabled" : "Disabled")
                </span>
            </div>
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" id="twoFactor"
                       checked="@TwoFactorEnabled"
                       @onchange="e => OnToggle2FA.InvokeAsync((bool)(e.Value ?? false))" />
            </div>
        </div>
    </div>

    @if (Security?.LastPasswordChange is not null)
    {
        <p class="text-muted small">
            Last password change: @Security.LastPasswordChange.Value.ToString("MMMM d, yyyy")
        </p>
    }

    <h6>Active Sessions</h6>
    @if (Security?.Sessions is { Count: > 0 })
    {
        <div class="table-responsive">
            <table class="table table-hover align-middle">
                <thead class="table-light">
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in Security.Sessions)
                    {
                        var isCurrent = session.Id == CurrentSessionId;
                        <tr>
                            <td>
                                @session.Device
                                @if (isCurrent)
                                {
                                    <span class="badge bg-primary ms-1">Current</span>
                                }
                            </td>
                            <td>@session.Location</td>
                            <td>@session.LastActive.ToString("g")</td>
                            <td>
                                @if (!isCurrent)
                                {
                                    <button class="btn btn-sm btn-outline-danger"
                                            @onclick="() => SessionToRevoke = session">
                                        Revoke
                                    </button>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    }
    else
    {
        <p class="text-muted">No active sessions found.</p>
    }
</div>

<RevokeSessionDialog Session="@SessionToRevoke"
                     OnConfirm="ConfirmRevoke"
                     OnCancel="() => SessionToRevoke = null" />

@code {
    [Parameter, EditorRequired]
    public SecuritySettings? Security { get; set; }

    [Parameter]
    public bool TwoFactorEnabled { get; set; }

    /// <summary>ID of the current browser session (excluded from revocation).</summary>
    [Parameter]
    public string CurrentSessionId { get; set; } = "";

    [Parameter, EditorRequired]
    public EventCallback<(string Current, string New)> OnChangePassword { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<bool> OnToggle2FA { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<string> OnRevokeSession { get; set; }

    private ActiveSession? SessionToRevoke { get; set; }

    private async Task ConfirmRevoke()
    {
        if (SessionToRevoke is not null)
        {
            await OnRevokeSession.InvokeAsync(SessionToRevoke.Id);
            SessionToRevoke = null;
        }
    }
}

@* Appearance settings with live preview *@

<div class="settings-section">
    <h4>Appearance</h4>
    <p class="text-muted">Customize how the application looks.</p>
    <hr />

    <div class="row">
        <div class="col-md-7">
            <div class="mb-4">
                <h6>Theme</h6>
                @foreach (var theme in new[] { "Light", "Dark", "System" })
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="theme"
                               id="@($"theme-{theme}")"
                               checked="@(EditTheme == theme)"
                               @onchange="() => EditTheme = theme" />
                        <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                    </div>
                }
            </div>

            <div class="mb-4">
                <h6>Font Size</h6>
                @foreach (var size in new[] { "Small", "Medium", "Large" })
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="fontSize"
                               id="@($"fs-{size}")"
                               checked="@(EditFontSize == size)"
                               @onchange="() => EditFontSize = size" />
                        <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                    </div>
                }
            </div>

            <div class="mb-4">
                <label class="form-label" for="language"><h6 class="d-inline">Language</h6></label>
                <select id="language" class="form-select w-auto"
                        @bind="EditLanguage">
                    <option value="en">English</option>
                    <option value="es">Español</option>
                    <option value="fr">Français</option>
                    <option value="de">Deutsch</option>
                    <option value="ja">日本語</option>
                    <option value="zh">中文</option>
                </select>
            </div>

            <div class="mb-4">
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="compactMode"
                           checked="@EditCompactMode"
                           @onchange="e => EditCompactMode = (bool)(e.Value ?? false)" />
                    <label class="form-check-label" for="compactMode">Compact Mode</label>
                </div>
            </div>

            <button class="btn btn-primary" @onclick="Save" disabled="@Saving">
                @if (Saving)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Save
            </button>
        </div>

        <div class="col-md-5">
            <h6>Preview</h6>
            <div class="preview-card @PreviewThemeClass" style="font-size: @PreviewFontSize;">
                <div class="preview-header">
                    <strong>Dashboard</strong>
                </div>
                <div class="preview-body" style="padding: @(EditCompactMode ? "0.5rem" : "1rem");">
                    <p class="preview-text">
                        Welcome back! You have <strong>3</strong> new notifications.
                    </p>
                    <div class="preview-items">
                        <div class="preview-item" style="padding: @(EditCompactMode ? "0.25rem 0.5rem" : "0.5rem 0.75rem");">Item 1</div>
                        <div class="preview-item" style="padding: @(EditCompactMode ? "0.25rem 0.5rem" : "0.5rem 0.75rem");">Item 2</div>
                        <div class="preview-item" style="padding: @(EditCompactMode ? "0.25rem 0.5rem" : "0.5rem 0.75rem");">Item 3</div>
                    </div>
                    <button class="preview-btn">Action</button>
                </div>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public AppearanceSettings? Appearance { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string EditTheme { get; set; } = "Light";
    private string EditFontSize { get; set; } = "Medium";
    private string EditLanguage { get; set; } = "en";
    private bool EditCompactMode { get; set; }
    private bool Saving { get; set; }

    private string PreviewThemeClass => EditTheme switch
    {
        "Dark" => "preview-dark",
        _ => "preview-light"
    };

    private string PreviewFontSize => EditFontSize switch
    {
        "Small" => "0.8rem",
        "Large" => "1.15rem",
        _ => "0.95rem"
    };

    protected override void OnParametersSet()
    {
        if (Appearance is not null)
        {
            EditTheme = Appearance.Theme;
            EditFontSize = Appearance.FontSize;
            EditLanguage = Appearance.Language;
            EditCompactMode = Appearance.CompactMode;
        }
    }

    private async Task Save()
    {
        Saving = true;
        var updated = new AppearanceSettings(EditTheme, EditFontSize, EditLanguage, EditCompactMode);
        await OnSave.InvokeAsync(updated);
        Saving = false;
    }
}

.preview-card {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    overflow: hidden;
    transition: all 0.2s ease;
}

.preview-light {
