    padding: 0.75rem 1rem;
}

.preview-dark .preview-item {
    background: #313244;
    border: 1px solid #45475a;
    border-radius: 0.25rem;
    margin-bottom: 0.375rem;
    color: #cdd6f4;
}

.preview-dark .preview-btn {
    background: #89b4fa;
    color: #1e1e2e;
    border: none;
    padding: 0.35rem 1rem;
    border-radius: 0.25rem;
    margin-top: 0.5rem;
    font-size: inherit;
    cursor: default;
}

.preview-text {
    margin-bottom: 0.75rem;
}

