@code {
    private string ActiveSection { get; set; } = "Profile";
    private bool Loading { get; set; } = true;

    // Data
    private UserProfile? Profile { get; set; }
    private UserProfile? SavedProfile { get; set; }
    private NotificationPrefs? NotifPrefs { get; set; }
    private SecuritySettings? Security { get; set; }
    private bool TwoFactorEnabled { get; set; }
    private AppearanceSettings? AppearancePrefs { get; set; }

    // The first session is treated as the current one
    private string CurrentSessionId => Security?.Sessions.FirstOrDefault()?.Id ?? "";

    private List<string> AllChannels { get; set; } =
        ["general", "announcements", "engineering", "design", "marketing", "random"];

    // Toast
    private string? ToastMessage { get; set; }
    private string ToastCssClass { get; set; } = "";
    private CancellationTokenSource? _toastCts;

    protected override async Task OnInitializedAsync()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifsTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifsTask, securityTask, appearanceTask);

        Profile = profileTask.Result;
        SavedProfile = Profile;
        NotifPrefs = notifsTask.Result;
        Security = securityTask.Result;
        TwoFactorEnabled = Security.TwoFactorEnabled;
        AppearancePrefs = appearanceTask.Result;

        Loading = false;
    }

    // --- Profile ---

    private async Task SaveProfile(UserProfile updated)
    {
        await SettingsService.SaveProfileAsync(updated);
        Profile = updated;
        SavedProfile = updated;
        await ShowToast("Profile saved successfully.", "success");
    }

    private Task DiscardProfile()
    {
        Profile = SavedProfile;
        return ShowToast("Changes discarded.", "info");
    }

    // --- Notifications ---

    private async Task SaveNotifications(NotificationPrefs prefs)
    {
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        NotifPrefs = prefs;
        await ShowToast("Notification preferences saved.", "success");
    }

    // --- Security ---

    private async Task HandleChangePassword((string Current, string New) args)
    {
        await SettingsService.ChangePasswordAsync(args.Current, args.New);
        Security = await SettingsService.GetSecuritySettingsAsync();
        await ShowToast("Password updated.", "success");
    }

    private async Task HandleToggle2FA(bool enabled)
    {
        TwoFactorEnabled = enabled;
        await ShowToast(
            enabled ? "Two-factor authentication enabled." : "Two-factor authentication disabled.",
            enabled ? "success" : "info");
    }

    private async Task HandleRevokeSession(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        Security = await SettingsService.GetSecuritySettingsAsync();
        await ShowToast("Session revoked.", "success");
    }

    // --- Appearance ---

    private async Task SaveAppearance(AppearanceSettings settings)
    {
        await SettingsService.SaveAppearanceAsync(settings);
        AppearancePrefs = settings;
        await ShowToast("Appearance settings saved.", "success");
    }

    // --- Toast helper ---

    private async Task ShowToast(string message, string type)
    {
        _toastCts?.Cancel();
        _toastCts = new CancellationTokenSource();
        var token = _toastCts.Token;

        ToastCssClass = $"toast-{type}";
        ToastMessage = message;
        StateHasChanged();

        try
        {
            await Task.Delay(3000, token);
            ToastMessage = null;
            StateHasChanged();
        }
        catch (TaskCanceledException)
        {
            // Another toast replaced this one
        }
    }
}

