toolArgs.file_text:
.settings-layout {
    display: flex;
    min-height: calc(100vh - 56px);
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    overflow: hidden;
    margin: 1.5rem;
    background: #fff;
}

.settings-nav {
    flex: 0 0 220px;
}

.settings-content {
    flex: 1;
    padding: 2rem;
    overflow-y: auto;
}

.settings-section h4 {
    margin-bottom: 0.25rem;
}

/* Toast */
.toast-bar {
    position: fixed;
    top: 1rem;
    right: 1rem;
    z-index: 1100;
    padding: 0.75rem 1.25rem;
    border-radius: 0.375rem;
    font-weight: 500;
    box-shadow: 0 0.25rem 0.75rem rgba(0, 0, 0, 0.15);
    animation: toast-slide-in 0.25s ease-out;
}

.toast-success {
    background: #d1e7dd;
    color: #0a3622;
    border: 1px solid #a3cfbb;
}

.toast-info {
    background: #cff4fc;
    color: #055160;
    border: 1px solid #9eeaf9;
}

.toast-error {
    background: #f8d7da;
    color: #58151c;
    border: 1px solid #f1aeb5;
}

@keyframes toast-slide-in {
    from {
        opacity: 0;
        transform: translateY(-0.5rem);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

